import fs from "node:fs";
import path from "node:path";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { runJiraOncall } from "../src/commands/jira-oncall.js";
import { runJiraReport } from "../src/commands/jira-report.js";
import { captureConsole, fixtures, normalize, tmpDir } from "./helpers.js";

// Goldens were generated by the original standalone tools (before the migration)
// from test/fixtures/Jira.csv. Only timestamps are normalized: the content is compared.
const golden = (name: string) => fs.readFileSync(path.join(fixtures, "golden", name), "utf-8");

let cwd: string;
let previousCwd: string;
let previousBaseUrl: string | undefined;

beforeEach(() => {
  // The oncall ticket prints today's date, so the clock is pinned to the day the goldens were made.
  vi.useFakeTimers({ toFake: ["Date"] });
  vi.setSystemTime(new Date("2026-11-24T12:00:00Z"));
  previousCwd = process.cwd();
  previousBaseUrl = process.env["JIRA_BASE_URL"];
  process.env["JIRA_BASE_URL"] = "https://your-company.atlassian.net";
  cwd = tmpDir();
  fs.copyFileSync(path.join(fixtures, "Jira.csv"), path.join(cwd, "Jira.csv"));
  process.chdir(cwd);
});

afterEach(() => {
  vi.useRealTimers();
  process.chdir(previousCwd);
  if (previousBaseUrl === undefined) delete process.env["JIRA_BASE_URL"];
  else process.env["JIRA_BASE_URL"] = previousBaseUrl;
});

const readOut = (dir: string, prefix: string) => {
  const file = fs.readdirSync(dir).find((f) => f.startsWith(prefix));
  if (!file) throw new Error(`no ${prefix}* in ${dir}`);
  return fs.readFileSync(path.join(dir, file), "utf-8");
};

describe("jira report parity", () => {
  it("matches the original output for all defects", () => {
    const { result, stdout } = captureConsole(() => runJiraReport("Jira.csv", undefined));
    expect(result).toBe(0);
    expect(normalize(stdout)).toBe(golden("report-all.stdout"));
    expect(normalize(readOut("reports", "report_Jira_2"))).toBe(golden("report-all.json"));
    expect(normalize(readOut("reports", "summary_Jira_2"))).toBe(golden("summary-all.json"));
  });

  it("matches the original output when filtering by person", () => {
    const { result, stdout } = captureConsole(() => runJiraReport("Jira.csv", "Daniel Quan"));
    expect(result).toBe(0);
    expect(normalize(stdout)).toBe(golden("report-person.stdout"));
    expect(normalize(readOut("reports", "report_Jira_Daniel_Quan_"))).toBe(golden("report-person.json"));
  });

  it("leaves url null when JIRA_BASE_URL is unset", () => {
    delete process.env["JIRA_BASE_URL"];
    captureConsole(() => runJiraReport("Jira.csv", undefined));
    const report = JSON.parse(readOut("reports", "report_Jira_2")) as { defects: { url: unknown }[] };
    expect(report.defects.every((d) => d.url === null)).toBe(true);
  });

  it("writes into --out instead of ./reports", () => {
    captureConsole(() => runJiraReport("Jira.csv", undefined, { out: "custom/dir" }));
    expect(fs.existsSync("reports")).toBe(false);
    expect(fs.readdirSync("custom/dir")).toHaveLength(2);
  });

  it("fails with exit code 1 for a missing file", () => {
    const { result, stderr } = captureConsole(() => runJiraReport("nope.csv", undefined));
    expect(result).toBe(1);
    expect(stderr).toContain("File not found: nope.csv");
  });

  it("exits 0 with a warning when the person has no defects", () => {
    const { result, stderr } = captureConsole(() => runJiraReport("Jira.csv", "Nobody Here"));
    expect(result).toBe(0);
    expect(stderr).toContain('No defects found for "Nobody Here"');
  });
});

describe("jira oncall parity", () => {
  it("matches the original ticket and console output", () => {
    captureConsole(() => runJiraReport("Jira.csv", undefined));
    const reportFile = fs.readdirSync("reports").find((f) => f.startsWith("report_Jira_2"))!;
    const { result, stdout } = captureConsole(() =>
      runJiraOncall(path.join("reports", reportFile), "Daniel Quan", "Sprint 42")
    );
    expect(result).toBe(0);
    expect(normalize(stdout)).toBe(golden("oncall.stdout"));
    expect(normalize(readOut("tickets", "oncall_Daniel_Quan_"))).toBe(golden("oncall.md"));
  });

  it("writes into --out instead of ./tickets", () => {
    captureConsole(() => runJiraReport("Jira.csv", undefined));
    const reportFile = fs.readdirSync("reports").find((f) => f.startsWith("report_Jira_2"))!;
    captureConsole(() => runJiraOncall(path.join("reports", reportFile), undefined, undefined, { out: "t" }));
    expect(fs.existsSync("tickets")).toBe(false);
    expect(fs.readdirSync("t")[0]).toMatch(/^oncall_Oncall_Engineer_/);
  });

  it("fails with exit code 1 for a missing report", () => {
    const { result } = captureConsole(() => runJiraOncall("nope.json", undefined, undefined));
    expect(result).toBe(1);
  });
});
